import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Concetto di operazione interna ed esterna","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/b_aritmetica-e-numeri/ba/bac.md","filePath":"lezioni/b_aritmetica-e-numeri/ba/bac.md"}`),a={name:`lezioni/b_aritmetica-e-numeri/ba/bac.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="concetto-di-operazione-interna-ed-esterna" tabindex="-1">Concetto di operazione interna ed esterna <a class="header-anchor" href="#concetto-di-operazione-interna-ed-esterna" aria-label="Permalink to “Concetto di operazione interna ed esterna”">​</a></h1><p>Un&#39;operazione su due oggetti è un qualche cosa che prende i due oggetti e li trasforma in un terzo oggetto.</p><p>Ora il terzo oggetto può:</p><ul><li><p>essere contenuto nell&#39;insieme in cui sono contenuti i due oggetti di base (e quindi l&#39;operazione si dice interna, e l&#39;insieme si dice chiuso rispetto a quella operazione)</p><blockquote><p>In pratica posso sempre fare l&#39;operazione</p></blockquote></li><li><p>non essere contenuto nell&#39;insieme in cui sono contenuti i due oggetti (e quindi l&#39;operazione si dice esterna, e l&#39;insieme si dice non chiuso rispetto a quella operazione)</p><blockquote><p>Non posso fare sempre l&#39;operazione</p></blockquote></li></ul><p><strong>Esempio:</strong></p><ul><li>La somma fra segmenti è un&#39;operazione interna perché il risultato è ancora un segmento</li><li>La somma fra triangoli non è un&#39;operazione interna perché il risultato di solito non è un triangolo</li></ul>`,6)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};